import React from "react";

const BestPokemon = props => {
  // Con Arrow Function
  return (
    <ul className="listaPokemon">
      {props.nombre.map((nombre, index) => {
        return <li key={index}>{nombre}</li>;
      })}
    </ul>
  );
};

export default BestPokemon;

